const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();

  // Set viewport to poster dimensions
  await page.setViewport({
    width: 1754,
    height: 2480,
    deviceScaleFactor: 2
  });

  const filePath = path.resolve(__dirname, 'poster.html');
  await page.goto('file://' + filePath, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for fonts and styles to settle
  await page.waitForTimeout(2000);

  // Take full-page screenshot
  await page.screenshot({
    path: path.resolve(__dirname, 'final_poster.png'),
    fullPage: false,
    type: 'png'
  });

  console.log('Poster captured successfully!');
  await browser.close();
})();

