'ss01';\n      width: 1754px; height: 2480px;\n      overflow: hidden; display: flex; flex-direction: column;\n    }\n    h1,h2,h3,h4,h5,h6 { color: var(--text); letter-spacing: -0.03em; line-height: 1.08; text-wrap: balance; }\n    h1 { font-weight: 700; }\n    h2 { font-weight: 600; }\n    h3 { font-weight: 500; }\n    body, p, li, td, th, span, label { font-weight: 400; }\n    p,li,td,th,span,label { color: var(--text); }\n    .text-secondary { color: var(--text-secondary); }\n\n    /* ===== POSTER STRUCTURE ===== */\n    .poster-header {\n      background: var(--header-bg);\n      color: #FFFFFF;\n      padding: 56px 64px 48px;\n      position: relative;\n      overflow: hidden;\n    }\n    .poster-header::after {\n      content: '';\n      position: absolute; bottom: 0; left: 0; right: 0; height: 4px;\n      background: linear-gradient(90deg, var(--wb-gold) 0%, #F1C40F 50%, var(--wb-gold) 100%);\n    }\n    .poster-header h1 {\n      font-size: 58px; font-weight: 700; color: #FFFFFF;\n      margin-bottom: 16px; line-height: 1.1;\n    }\n    .poster-header .subtitle {\n      font-size: 22px; color: rgba(255,255,255,0.85);\n      line-height: 1.5; max-width: 1400px; font-weight: 300;\n    }\n    .poster-header .wb-badge {\n      display: inline-flex; align-items: center; gap: 8px;\n      font-size: 13px; color: rgba(255,255,255,0.6);\n      text-transform: uppercase; letter-spacing: 0.08em;\n      margin-bottom: 20px;\n    }\n    .poster-header .wb-badge svg { opacity: 0.6; }\n\n    .poster-body {\n      flex: 1; display: flex; flex-direction: column;\n      padding: 40px 64px 32px; gap: 36px;\n    }\n\n    /* ===== SECTION STYLES ===== */\n    .section-title {\n      font-size: 28px; font-weight: 700; color: var(--wb-navy);\n      margin-bottom: 20px; display: flex; align-items: center; gap: 14px;\n      letter-spacing: -0.02em;\n    }\n    .section-title::before {\n      content: ''; display: inline-block; width: 5px; height: 28px;\n      background: var(--wb-teal); border-radius: 2px; flex-shrink: 0;\n    }\n    html.theme-dark .section-title { color: #5DADE2; }\n\n    /* ===== RECOVERY SECTION ===== */\n    .recovery-section {\n      display: flex; gap: 40px; align-items: stretch;\n    }\n    .recovery-hero {\n      flex: 0 0 480px; background: linear-gradient(135deg, #003366 0%, #1A5276 100%);\n      border-radius: 12px; padding: 40px 36px;\n      display: flex; flex-direction: column; justify-content: center;\n      position: relative; overflow: hidden;\n    }\n    .recovery-hero::before {\n      content: ''; position: absolute; top: -40px; right: -40px;\n      width: 200px; height: 200px; border-radius: 50%;\n      background: rgba(212,172,13,0.1);\n    }\n    .recovery-hero .metric-value {\n      font-size: 56px; font-weight: 800; color: #F1C40F;\n      line-height: 1.05; margin-bottom: 12px;\n    }\n    .recovery-hero .metric-label {\n      font-size: 18px; color: rgba(255,255,255,0.8);\n      font-weight: 400; line-height: 1.4;\n    }\n    .recovery-hero .metric-badge {\n      display: inline-block; margin-top: 16px;\n      background: rgba(241,196,15,0.15); color: #F1C40F;\n      padding: 6px 14px; border-radius: 20px;\n      font-size: 13px; font-weight: 600;\n      text-transform: uppercase; letter-spacing: 0.05em;\n    }\n    .recovery-text {\n      flex: 1; display: flex; flex-direction: column; justify-content: center;\n      padding: 12px 0;\n    }\n    .recovery-text p {\n      font-size: 19px; line-height: 1.65; color: var(--text-secondary);\n      margin-bottom: 16px;\n    }\n    .recovery-text p:last-child { margin-bottom: 0; }\n    .recovery-text .highlight {\n      color: var(--text); font-weight: 500;\n    }\n\n    /* ===== RISKS SECTION ===== */\n    .risks-grid {\n      display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px;\n    }\n    .risk-card {\n      background: var(--surface); border: 1px solid var(--border);\n      border-radius: 10px; padding: 28px 24px;\n      position: relative;