r-row { background: rgba(93,173,226,0.06); }\n    .policy-header-row > div {\n      padding: 16px 20px; font-size: 13px; font-weight: 700;\n      text-transform: uppercase; letter-spacing: 0.05em;\n      color: var(--wb-navy);\n    }\n    html.theme-dark .policy-header-row > div { color: #5DADE2; }\n    .policy-row { border-top: 1px solid var(--border); }\n    .policy-row > div { padding: 16px 20px; font-size: 15px; line-height: 1.5; }\n    .policy-row > div:first-child {\n      font-weight: 700; color: var(--text);\n      display: flex; align-items: center; gap: 10px;\n    }\n    .policy-row > div:nth-child(2),\n    .policy-row > div:nth-child(3) {\n      color: var(--text-secondary);\n    }\n    .policy-row .policy-icon {\n      width: 28px; height: 28px; border-radius: 6px;\n      background: rgba(23,165,137,0.1);\n      display: flex; align-items: center; justify-content: center; flex-shrink: 0;\n    }\n    .policy-row .policy-icon svg {\n      width: 16px; height: 16px; stroke: var(--wb-teal); fill: none; stroke-width: 2;\n    }\n\n    /* ===== PRIORITIES SECTION ===== */\n    .priorities-header {\n      display: flex; align-items: center; gap: 32px;\n      margin-bottom: 24px;\n    }\n    .priorities-hero-metric {\n      background: linear-gradient(135deg, #003366 0%, #1A5276 100%);\n      border-radius: 12px; padding: 28px 36px;\n      display: flex; align-items: center; gap: 20px;\n      flex-shrink: 0;\n    }\n    .priorities-hero-metric .big-num {\n      font-size: 52px; font-weight: 800; color: #F1C40F; line-height: 1;\n    }\n    .priorities-hero-metric .big-label {\n      font-size: 16px; color: rgba(255,255,255,0.8); line-height: 1.4;\n    }\n    .priorities-intro {\n      font-size: 18px; color: var(--text-secondary); line-height: 1.6;\n    }\n    .priorities-grid {\n      display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px;\n    }\n    .priority-card {\n      background: var(--surface); border: 1px solid var(--border);\n      border-radius: 10px; padding: 24px 20px;\n      text-align: center; position: relative;\n      transition: box-shadow 0.2s ease;\n    }\n    .priority-card:hover {\n      box-shadow: 0 4px 16px rgba(0,0,0,0.08);\n    }\n    .priority-card .priority-value {\n      font-size: 36px; font-weight: 800; color: #D4AC0F;\n      line-height: 1.1; margin-bottom: 6px;\n    }\n    html.theme-dark .priority-card .priority-value { color: #F1C40F; }\n    .priority-card .priority-unit {\n      font-size: 13px; color: var(--text-secondary); margin-bottom: 14px;\n      font-weight: 400;\n    }\n    .priority-card .priority-name {\n      font-size: 15px; font-weight: 700; color: var(--text);\n      margin-bottom: 6px;\n    }\n    .priority-card .priority-desc {\n      font-size: 12.5px; color: var(--text-secondary); line-height: 1.45;\n    }\n    .priority-card .priority-icon-bar {\n      width: 32px; height: 3px; border-radius: 2px;\n      background: var(--wb-teal); margin: 0 auto 14px;\n    }\n\n    /* ===== RESEARCH THEMES ===== */\n    .research-grid {\n      display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px;\n    }\n    .research-col {\n      padding: 16px; border-radius: 8px;\n      background: rgba(26,82,118,0.03);\n    }\n    html.theme-dark .research-col { background: rgba(93,173,226,0.04); }\n    .research-col h4 {\n      font-size: 13px; font-weight: 700; color: var(--wb-navy);\n      text-transform: uppercase; letter-spacing: 0.04em;\n      margin-bottom: 10px;\n    }\n    html.theme-dark .research-col h4 { color: #5DADE2; }\n    .research-col .topic {\n      font-size: 12.5px; color: var(--text-secondary);\n      line-height: 1.5; margin-bottom: 6px;\n    }\n    .research-col .topic:last-child { margin-bottom: 0; }\n    .research-col .topic-date {\n      font-size: 11px; color: var(--text-secondary); opacity: 0.6;\n    }\n\n    /* ===== CHART SECTION ===== */\n    .chart-row {\n      display: flex; gap: 28px; align-items: stretch;\n    }\n    .chart-container-wrap {\n      flex: 1; background: var(--surface); border: 1px solid var(--border);\n      border-radius: 10px; padding: 28px; min-height: 280px;\n    }\n\n    /* ===== DIVIDERS ===== */\n    .section-divider {\n      width: 100%; height: 1px;\n      background: var(--border);\n      margin: 4px 0;\n    }\n\n    /* ===== ANIMATIONS ===== */\n    @keyframes fadeInUp {\n      from { opacity: 0; transform: translateY(24px); }\n      to { opacity: 1; transform: translateY(0); }\n    }\n    .animate { animation: fadeInUp 0.6s ease-out both; }\n    .animate.delay-1 { animation-delay: 0.1s; }\n    .animate.delay-2 { animation-delay: 0.2s; }\n    .animate.delay-3 { animation-delay: 0.3s; }\n    .animate.delay-4 { animation-delay: 0.4s; }\n    .animate.delay-5 { animation-delay: 0.5s; }\n\n    /* ===== FOOTER ===== */\n    .poster-footer {\n      padding: 20px 64px;\n      border-top: 1px solid var(--border);\n      display: flex; justify-content: space-between; align-items: center;\n      font-size: 12px; color: var(--text-secondary);\n    }\n\n    /* ===== PRINT ===== */\n    @media print {\n      body { width: auto; height: auto; overflow: visible; background: white !important; color: black !important; }\n      .viz-menu { display: none !important; }\n      * { print-color-adjust: exact; -webkit-print-color-adjust: exact; }\n    }\n    @media (prefers-reduced-motion: reduce) {\n      *, *::before, *::after { animation: none !important; transition: none !important; }\n    }\n  </style>\n</head>\n<body>\n  <main id=\"main-content\" role=\"main\" style=\"display:flex;flex-direction:column;height:100%;\">\n\n    <!-- HEADER -->\n    <header class=\"poster-header animate\" role=\"banner\">\n      <div class=\"wb-badge\">\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M2 12h20M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"/></svg>\n        World Bank Group &mdash; Global Economic Prospects\n      </div>\n      <h1>Global Economic Prospects:<br>Resilience Amid Uncertainty</h1>\n      <p class=\"subtitle\">The global economy has recovered strongly from the 2020 recession, but vulnerable economies lag behind as trade tensions and policy uncertainty cloud the outlook.</p>\n    </header>\n\n    <!-- POSTER BODY -->\n    <div class=\"poster-body\">\n\n      <!-- SECTION 1: HISTORIC RECOVERY -->\n      <section class=\"animate delay-1\" aria-label=\"Historic Recovery\">\n        <h2 class=\"section-title\">A Historic Recovery &mdash; But Uneven</h2>\n        <div class=\"recovery-section\">\n          <div class=\"recovery-hero\">\n            <div class=\"metric-value\" data-count=\"6\" data-suffix=\" Decades\">6 Decades</div>\n            <div class=\"metric-label\">Post-2020 Recovery Benchmark &mdash; Strongest recovery in six decades</div>\n            <div class=\"metric-badge\">Unmatched Resilience</div>\n          </div>\n          <div class=\"recovery-text\">\n            <p>The global economy has demonstrated <span class=\"highlight\">notable resilience</span> in the face of heightened trade tensions and policy uncertainty. Last year's faster-than-expected growth capped a recovery from the 2020 recession that is <span class=\"highlight\">unmatched in six decades</span>.</p>\n            <p>However, this headline resilience masks a <span class=\"highlight\">widening gap</span>: vulnerable emerging market and developing economies (EMDEs) continue to lag significantly behind advanced economies and more robust peers. Growth is projected to edge downward, driven by firms scaling back inventory accumulation and intensifying tariff effects.</p>\n          </div>\n        </div>\n      </section>\n\n      <div class=\"section-divider\"></div>\n\n      <!-- SECTION 2: RISKS -->\n      <section class=\"animate delay-2\" aria-label=\"Risks to the Outlook\">\n        <h2 class=\"section-title\">Risks to the Outlook</h2>\n        <div class=\"risks-grid\">\n          <div class=\"risk-card\">\n            <div class=\"risk-icon\">\n              <svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"/><path d=\"M2 17l10 5 10-5\"/><path d=\"M2 12l10 5 10-5\"/></svg>\n            </div>\n            <h3>Trade Tensions</h3>\n            <p>Escalation of tariffs and retaliatory measures could disrupt supply chains and dampen investment globally.</p>\n            <span class=\"risk-severity severity-high\">High Risk</span>\n          </div>\n          <div class=\"risk-card\">\n            <div class=\"risk-icon\">\n              <svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"22 12 18 12 15 21 9 3 6 12 2 12\"/></svg>\n            </div>\n            <h3>Financial Volatility</h3>\n            <p>Deterioration in sentiment could tighten financing conditions, especially for EMDEs dependent on external capital.</p>\n            <span class=\"risk-severity severity-high\">High Risk</span>\n          </div>\n          <div class=\"risk-card\">\n            <div class=\"risk-icon\">\n              <svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z\"/><path d=\"M3.27 6.96L12 12.01l8.73-5.05\"/><path d=\"M12 22.08V12\"/></svg>\n            </div>\n            <h3>Inventory Correction</h3>\n            <p>Firms that front-loaded purchases are now drawing down stocks, reducing near-term demand and output.</p>\n            <span class=\"risk-severity severity-med\">Medium Risk</span>\n          </div>\n          <div class=\"risk-card\">\n            <div class=\"risk-icon\">\n              <svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9z\"/></svg>\n            </div>\n            <h3>Climate Shocks</h3>\n            <p>Extreme weather events continue to threaten agricultural output and infrastructure in vulnerable regions.</p>\n            <span class=\"risk-severity severity-med\">Medium Risk</span>\n          </div>\n        </div>\n      </section>\n\n      <div class=\"section-divider\"></div>\n\n      <!-- SECTION 3: POLICY ACTIONS -->\n      <section class=\"animate delay-3\" aria-label=\"Policy Actions\">\n        <h2 class=\"section-title\">Policy Actions for Sustained Growth</h2>\n        <div class=\"policy-grid\">\n          <div class=\"policy-header-row\">\n            <div>Reform Area</div>\n            <div>Global Action</div>\n            <div>Domestic Action</div>\n          </div>\n          <div class=\"policy-row\">\n            <div>\n              <span class=\"policy-icon\"><svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"/><path d=\"M2 17l10 5 10-5\"/></svg></span>\n              Trade\n            </div>\n            <div>Improve the multilateral trade environment</div>\n            <div>Diversify trade partners and products</div>\n          </div>\n          <div class=\"policy-row\">\n            <div>\n              <span class=\"policy-icon\"><svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"12\" y1=\"1\" x2=\"12\" y2=\"23\"/><path d=\"M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6\"/></svg></span>\n              Finance\n            </div>\n            <div>Ease external financing constraints for EMDEs</div>\n            <div>Strengthen macroeconomic policy frameworks</div>\n          </div>\n          <div class=\"policy-row\">\n            <div>\n              <span class=\"policy-icon\"><svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9z\"/></svg></span>\n              Climate\n            </div>\n            <div>Scale up climate risk mitigation and adaptation</div>\n            <div>Invest in resilient infrastructure</div>\n          </div>\n          <div class=\"policy-row\">\n            <div>\n              <span class=\"policy-icon\"><svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"23 6 13.5 15.5 8.5 10.5 1 18\"/><polyline points=\"17 6 23 6 23 12\"/></svg></span>\n              Investment\n            </div>\n            <div>Catalyze private capital flows</div>\n            <div>Remove structural bottlenecks to business entry</div>\n          </div>\n          <div class=\"policy-row\">\n            <div>\n              <span class=\"policy-icon\"><svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg></span>\n              Jobs\n            </div>\n            <div>Support cross-border labor mobility</div>\n            <div>Enhance skills development and labor market flexibility</div>\n          </div>\n        </div>\n      </section>\n\n      <div class=\"section-divider\"></div>\n\n      <!-- SECTION 4: 2030 PRIORITIES -->\n      <section class=\"animate delay-4\" aria-label=\"2030 Strategic Priorities\">\n        <h2 class=\"section-title\">World Bank 2030 Strategic Priorities</h2>\n        <div class=\"priorities-header\">\n          <div class=\"priorities-hero-metric\">\n            <div class=\"big-num\">1.2B</div>\n            <div class=\"big-label\">Youth entering<br>working age<br>(next decade)</div>\n          </div>\n          <p class=\"priorities-intro\">Job creation is central to the World Bank Group's mission. The Bank has set ambitious 2030 targets across five flagship initiatives to drive inclusive, sustainable growth.</p>\n        </div>\n        <div class=\"priorities-grid\">\n          <div class=\"priority-card\">\n            <div class=\"priority-icon-bar\"></div>\n            <div class=\"priority-value\">1.5B</div>\n            <div class=\"priority-unit\">people</div>\n            <div class=\"priority-name\">Health Services</div>\n            <div class=\"priority-desc\">Deliver quality, affordable health services</div>\n          </div>\n          <div class=\"priority-card\">\n            <div class=\"priority-icon-bar\"></div>\n            <div class=\"priority-value\">300M</div>\n            <div class=\"priority-unit\">people</div>\n            <div class=\"priority-name\">Mission 300</div>\n            <div class=\"priority-desc\">Electricity access in Sub-Saharan Africa</div>\n          </div>\n          <div class=\"priority-card\">\n            <div class=\"priority-icon-bar\"></div>\n            <div class=\"priority-value\">300M</div>\n            <div class=\"priority-unit\">farmers</div>\n            <div class=\"priority-name\">AgriConnect</div>\n            <div class=\"priority-desc\">Farmers up the agricultural value chain</div>\n          </div>\n          <div class=\"priority-card\">\n            <div class=\"priority-icon-bar\"></div>\n            <div class=\"priority-value\">80M</div>\n            <div class=\"priority-unit\">women</div>\n            <div class=\"priority-name\">Capital Support</div>\n            <div class=\"priority-desc\">Women & women-led businesses with capital access</div>\n          </div>\n          <div class=\"priority-card\">\n            <div class=\"priority-icon-bar\"></div>\n            <div class=\"priority-value\">1B+</div>\n            <div class=\"priority-unit\">people</div>\n            <div class=\"priority-name\">Water Forward</div>\n            <div class=\"priority-desc\">Water security; 400M WBG commitment</div>\n          </div>\n        </div>\n      </section>\n\n      <div class=\"section-divider\"></div>\n\n      <!-- SECTION 5: RESEARCH THEMES -->\n      <section class=\"animate delay-5\" aria-label=\"Research Themes\">\n        <h2 class=\"section-title\">Key Research Themes in Recent Issues</h2>\n        <div class=\"research-grid\">\n          <div class=\"research-col\">\n            <h4>Fiscal Policy</h4>\n            <div class=\"topic\">Fiscal rules for rebuilding fiscal space <span class=\"topic-date\">(Jan. 2026)</span></div>\n            <div class=\"topic\">Fiscal challenges in small states <span class=\"topic-date\">(June 2024)</span></div>\n          </div>\n          <div class=\"research-col\">\n            <h4>Trade &amp; Supply Chains</h4>\n            <div class=\"topic\">High trade costs &mdash; causes and remedies <span class=\"topic-date\">(June 2021)</span></div>\n            <div class=\"topic\">COVID-19 impact on global value chains <span class=\"topic-date\">(June 2020)</span></div>\n          </div>\n          <div class=\"research-col\">\n            <h4>Commodity Markets</h4>\n            <div class=\"topic\">Commodity price cycles &mdash; drivers and policies <span class=\"topic-date\">(Jan. 2022)</span></div>\n            <div class=\"topic\">Russia-Ukraine energy implications <span class=\"topic-date\">(June 2022)</span></div>\n          </div>\n          <div class=\"research-col\">\n            <h4>Financial Spillovers</h4>\n            <div class=\"topic\">Rising U.S. interest rates <span class=\"topic-date\">(June 2023)</span></div>\n            <div class=\"topic\">Fourth wave of rapid debt buildup <span class=\"topic-date\">(Jan. 2020)</span></div>\n          </div>\n          <div class=\"research-col\">\n            <h4>Pandemic Economics</h4>\n            <div class=\"topic\">COVID-19 impact on global income inequality <span class=\"topic-date\">(Jan. 2022)</span></div>\n            <div class=\"topic\">Regional macro implications <span class=\"topic-date\">(June 2020)</span></div>\n          </div>\n        </div>\n      </section>\n\n    </div>\n\n    <!-- FOOTER -->\n    <footer class=\"poster-footer\">\n      <span>Source: World Bank Group &mdash; Global Economic Prospects Report Series</span>\n      <span>World Bank 2030 Strategic Priorities &bull; Resilience Amid Uncertainty</span>\n    </footer>\n\n  </main>\n\n  <script>\n    // Menu\n    function toggleMenu() {\n      var d = document.getElementById('vizMenuDropdown');\n      if (d) d.classList.toggle('open');\n    }\n\n    // Theme\n    var currentTheme = 'light';\n    function applyTheme(t) {\n      document.documentElement.className = 'theme-' + t;\n      currentTheme = t;\n    }\n    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }\n    applyTheme('light');\n\n    // Scroll reveal\n    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });\n    var revealObserver = new IntersectionObserver(function(entries) {\n      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });\n    }, { threshold: 0.15 });\n    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });\n\n    // Number counter\n    function animateCounters() {\n      document.querySelectorAll('[data-count]').forEach(function(el) {\n        if (el.dataset.counted) return;\n        el.dataset.counted = '1';\n        var target = parseFloat(el.dataset.count), prefix = el.dataset.prefix || '', suffix = el.dataset.suffix || '';\n        var start = performance.now(), duration = 1200;\n        (function tick(now) {\n          var p = Math.min((now - start) / duration, 1), eased = 1 - Math.pow(1 - p, 3);\n          el.textContent = prefix + Math.round(target * eased).toLocaleString() + suffix;\n          if (p < 1) requestAnimationFrame(tick);\n        })(start);\n      });\n    }\n\n    // Download PNG\n    async function downloadImage() {\n      var menu = document.querySelector('.viz-menu');\n      if (menu) menu.style.display = 'none';\n      try {\n        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2 });\n        var a = document.createElement('a'); a.href = url;\n        a.download = 'global-economic-prospects-poster.png'; a.click();\n      } catch(e) { console.error('Download failed:', e); }\n      if (menu) menu.style.display = '';\n    }\n  </script>\n</body>\n</html>", "numLines": 621, "startLine": 1, "totalLines": 621}}

